//const analysis = $('Question Analyzer').first().json;
const analysisText = $('Question Analyzer').first().json.output[0].content[0].text;

const analysis = JSON.parse(analysisText);

const solution = $('Solver').first().json.output[0].content[0].text;

const examiner = $('Examiner').first().json.output[0].content[0].text;

const replyToken = $('Download Image').first().json.replyToken;

const output = `
Topic: ${analysis.topic}
Difficulty: ${analysis.difficulty}
Assessment Objective: ${analysis.assessmentObjective}
━━━━━━━━━━━━━━━━━━
Solution

${solution}
━━━━━━━━━━━━━━━━━━
${examiner}
`;

return [
  {
    json: {
      replyToken,
      formatted_output: output
    }
  }
];

